import csv
from collections import deque

def compute_moving_average(prices, window=20):
    """Compute the moving average for a list of prices."""
    if not prices:
        return 0
    return sum(prices) / len(prices)

def read_stock_data(filename):
    """Read stock data from CSV file and return a dictionary of stock names and their prices."""
    stocks = {}
    try:
    with open(filename, 'r') as file:
        reader = csv.reader(file)
        header = next(reader)  # Skip header row
        for row in reader:
            try:
                stock_name = row[0]
                price = float(row[1])
                if stock_name not in stocks:
                    stocks[stock_name] = []
                stocks[stock_name].append(price)
            except (ValueError, IndexError):
                # Skip malformed rows
                continue
    except FileNotFoundError:
        print(f"Error: File '{filename}' not found.")
        return {}
    except Exception as e:
        print(f"Error reading file: {e}")
        return {}
    return stocks

